    // An appointment as the job panel sees it: { jobId, jobTotal, businessUnitId, appointment:
    // { id, number, start, end, status, techIds } }, or throws.
    // Anything missing or odd is refused (and the run says why), rather than guessed: a missing
    // total read as $0 would skip the managed-tech rule, a missing status would hide a Done job.
    // ms: a shorter time limit, for the quick re-reads that confirm a change.
    const appointment = async (apptId, ms) => {
      const d = await getJSON('/dispatch/job-edit-flyout/GetJobEditFlyoutData?appointmentId=' + encodeURIComponent(apptId), ms);
      const a = d && Array.isArray(d.jobAppointments) ? d.jobAppointments.find(x => x && String(x.id) === String(apptId)) : null;
      const shape = what => fail('bad', 'the appointment came back in a shape the Toolbox doesn\'t know (' + what + ')');
      if (!a || !Array.isArray(a.technicians)) throw shape('no technicians');
      if (a.technicians.some(t => !t || t.id == null)) throw shape('a technician without an id');
      if (d.jobId == null) throw shape('no job number');
      if (typeof d.jobTotal !== 'number' || !isFinite(d.jobTotal)) throw shape('no job total');
      // Seen Oct 2026: a number (0 = Scheduled, 4 = Done). Older pages used words.
      if (typeof a.jobAppointmentStatus !== 'number' && !(typeof a.jobAppointmentStatus === 'string' && norm(a.jobAppointmentStatus))) throw shape('no status');
      if (!a.start || !a.end || isNaN(new Date(a.start)) || isNaN(new Date(a.end))) throw shape('no start or end time');
      return {
        jobId: d.jobId, jobTotal: d.jobTotal, businessUnitId: d.businessUnitId,
        appointment: { id: a.id, number: a.number, start: a.start, end: a.end, status: a.jobAppointmentStatus, techIds: a.technicians.map(t => t.id),
          windowStart: a.arrivalWindowStart || null, windowEnd: a.arrivalWindowEnd || null }
      };
    };
    // A job's overview: { summary (as ServiceTitan keeps it, often HTML, or ''), skills ([{ id, name }],
    // active ones only; null if the answer has none) }. One request gives both (🧭 Tech Router keeps
    // it, so a job's summary and skills are read once).
    const jobOverview = async jobId => {
      const d = await getJSON('/dispatch/job-edit-flyout/GetJobOverviewData?jobId=' + encodeURIComponent(jobId));
      if (!d || typeof d !== 'object' || Array.isArray(d)) throw fail('bad', 'the job overview came back in a shape the Toolbox doesn\'t know');
      const tags = v => (Array.isArray(v) ? v : []).map(t => t && norm(t.name) ? { name: norm(t.name), color: norm(t.color) || '#e3e5e8', textColor: norm(t.textColor) } : null).filter(Boolean);
      const idName = v => v && typeof v === 'object' && v.id ? { id: String(v.id), name: norm(v.name) } : null;
      // Also (📋 Quick Job Info, seen Nov 2026): its tags (jobTags) and the customer's and location's
      // (otherTags), with ServiceTitan's colors; business unit, campaign, the invoice's subtotal, the job
      // it's a recall or warranty of, and the equipment installed there.
      return { summary: typeof d.jobSummary === 'string' ? d.jobSummary : '', skills: Array.isArray(d.skills) ? d.skills.filter(s => s && s.active !== false).map(s => ({ id: s.id, name: norm(s.name) })) : null,
        jobTags: tags(d.jobTags), otherTags: tags(d.otherTags), bu: idName(d.businessUnit), campaign: idName(d.campaign),
        invoice: d.invoice && typeof d.invoice.subtotal === 'number' ? d.invoice.subtotal : null, recallFor: idName(d.recallFor), warrantyFor: idName(d.warrantyFor),
        equipment: (Array.isArray(d.installedEquipment) ? d.installedEquipment : []).filter(e => e && (norm(e.name) || norm(e.model))).map(e => ({ name: norm(e.name), model: norm(e.model), installed: e.installedOn ? new Date(e.installedOn) : null })) };
    };
    // The skills a job needs: [{ id, name }] (active ones only).
    const skillsOf = v => { if (!v.skills) throw fail('bad', 'the job overview came back in a shape the Toolbox doesn\'t know'); return v.skills; };
    const jobSkills = async jobId => skillsOf(await jobOverview(jobId));
    // A job's summary, or '' (🧭 Tech Router reads it for a customer's time request).
    const jobSummary = async jobId => (await jobOverview(jobId)).summary;
    // The notes on a customer, location or job (ownerId), as the notes panel lists them (seen Oct 31
    // 2026: { pinnedNotes, notes, count }): [{ text, at (Date or null), pinned }], archived ones left out.
    const ownerNotes = async ownerId => {
      const d = await getJSON('/app/api/notes/Find?ownerId=' + encodeURIComponent(ownerId));
      if (!d || typeof d !== 'object' || (d.notes != null && !Array.isArray(d.notes)) || (d.pinnedNotes != null && !Array.isArray(d.pinnedNotes))) throw fail('bad', 'the notes came back in a shape the Toolbox doesn\'t know');
      const seen = new Set();
      return (d.pinnedNotes || []).map(n => Object.assign({}, n, { isPinned: true })).concat(d.notes || []).filter(n => n && typeof n.text === 'string' && !n.archived && n.active !== false && !(n.id != null && seen.has(n.id)) && (n.id == null || !!seen.add(n.id)))
        .map(n => { const at = n.createdOn ? new Date(n.createdOn) : null; return { text: n.text, at: at && !isNaN(at) ? at : null, pinned: !!n.isPinned }; });
    };
