        // two jobs at the same time, where neither can move on its own.)
        if (!best) break;
        best.stops.forEach(([R, stops, sim]) => { R.stops = stops; sims.set(R.t.id, sim); });
        best.after = best.stops.map(([R, , sim]) => [R, sim]);
